//! Routing result types.
//!
//! Types for representing autorouting results from FreeRouting.

use cypcb_core::{Nm, Point};
use cypcb_world::{Layer, NetId};

/// Status of the routing operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RoutingStatus {
    /// All nets successfully routed.
    Complete,
    /// Some nets could not be routed.
    Partial {
        /// Number of connections that could not be routed.
        unrouted_count: usize,
    },
    /// Routing failed completely.
    Failed {
        /// Error message or reason for failure.
        reason: String,
    },
}

impl RoutingStatus {
    /// Check if routing completed successfully.
    pub fn is_complete(&self) -> bool {
        matches!(self, RoutingStatus::Complete)
    }

    /// Check if routing failed.
    pub fn is_failed(&self) -> bool {
        matches!(self, RoutingStatus::Failed { .. })
    }
}

/// A single routed trace segment.
///
/// Represents a wire segment from the autorouter output.
/// Multiple segments form a complete trace path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RouteSegment {
    /// The net this segment belongs to.
    pub net_id: NetId,
    /// Which copper layer this segment is on.
    pub layer: Layer,
    /// Trace width in nanometers.
    pub width: Nm,
    /// Start point of the segment.
    pub start: Point,
    /// End point of the segment.
    pub end: Point,
}

impl RouteSegment {
    /// Create a new route segment.
    pub fn new(net_id: NetId, layer: Layer, width: Nm, start: Point, end: Point) -> Self {
        RouteSegment {
            net_id,
            layer,
            width,
            start,
            end,
        }
    }

    /// Calculate the length of this segment in nanometers.
    pub fn length(&self) -> Nm {
        let dx = self.end.x.0 - self.start.x.0;
        let dy = self.end.y.0 - self.start.y.0;

        // Use i128 to prevent overflow during squared calculation
        let dx_squared = (dx as i128) * (dx as i128);
        let dy_squared = (dy as i128) * (dy as i128);

        let sum = dx_squared + dy_squared;
        let length = (sum as f64).sqrt() as i64;

        Nm(length)
    }
}

/// A via placement from the autorouter.
///
/// Vias connect traces between different copper layers.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ViaPlacement {
    /// The net this via belongs to.
    pub net_id: NetId,
    /// Center position of the via.
    pub position: Point,
    /// Drill hole diameter in nanometers.
    pub drill: Nm,
    /// Upper layer connection (typically TopCopper).
    pub start_layer: Layer,
    /// Lower layer connection (typically BottomCopper).
    pub end_layer: Layer,
}

impl ViaPlacement {
    /// Create a new via placement.
    pub fn new(
        net_id: NetId,
        position: Point,
        drill: Nm,
        start_layer: Layer,
        end_layer: Layer,
    ) -> Self {
        ViaPlacement {
            net_id,
            position,
            drill,
            start_layer,
            end_layer,
        }
    }

    /// Create a through-hole via (top to bottom copper).
    pub fn through_hole(net_id: NetId, position: Point, drill: Nm) -> Self {
        ViaPlacement {
            net_id,
            position,
            drill,
            start_layer: Layer::TopCopper,
            end_layer: Layer::BottomCopper,
        }
    }
}

/// Result of an autorouting operation.
///
/// Contains the routing status and all generated routes and vias.
#[derive(Debug, Clone)]
pub struct RoutingResult {
    /// Status of the routing operation.
    pub status: RoutingStatus,
    /// Generated trace segments.
    pub routes: Vec<RouteSegment>,
    /// Generated via placements.
    pub vias: Vec<ViaPlacement>,
}

impl RoutingResult {
    /// Create a successful routing result.
    pub fn complete(routes: Vec<RouteSegment>, vias: Vec<ViaPlacement>) -> Self {
        RoutingResult {
            status: RoutingStatus::Complete,
            routes,
            vias,
        }
    }

    /// Create a partial routing result.
    pub fn partial(
        routes: Vec<RouteSegment>,
        vias: Vec<ViaPlacement>,
        unrouted_count: usize,
    ) -> Self {
        RoutingResult {
            status: RoutingStatus::Partial { unrouted_count },
            routes,
            vias,
        }
    }

    /// Create a failed routing result.
    pub fn failed(reason: impl Into<String>) -> Self {
        RoutingResult {
            status: RoutingStatus::Failed {
                reason: reason.into(),
            },
            routes: Vec::new(),
            vias: Vec::new(),
        }
    }

    /// Check if routing completed successfully.
    pub fn is_complete(&self) -> bool {
        self.status.is_complete()
    }

    /// Get the total number of route segments.
    pub fn route_count(&self) -> usize {
        self.routes.len()
    }

    /// Get the total number of vias.
    pub fn via_count(&self) -> usize {
        self.vias.len()
    }

    /// Calculate the total routed wire length.
    pub fn total_length(&self) -> Nm {
        let total: i64 = self.routes.iter().map(|r| r.length().0).sum();
        Nm(total)
    }
}

impl Default for RoutingResult {
    fn default() -> Self {
        RoutingResult {
            status: RoutingStatus::Complete,
            routes: Vec::new(),
            vias: Vec::new(),
        }
    }
}

/// Quality metrics for routing results.
///
/// Used to evaluate the "satisfaction score" of a routing solution.
/// Lower values generally indicate better routing quality.
///
/// # Example
///
/// ```
/// use cypcb_router::types::RoutingMetrics;
/// use cypcb_core::Nm;
///
/// let metrics = RoutingMetrics {
///     total_length: Nm::from_mm(150.0),
///     via_count: 5,
///     layer_changes: 5,
///     unrouted_nets: 0,
/// };
///
/// assert!(metrics.is_complete());
/// ```
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RoutingMetrics {
    /// Total routed wire length in nanometers.
    pub total_length: Nm,

    /// Number of vias used.
    pub via_count: u32,

    /// Number of layer changes (equals via_count for simple designs).
    pub layer_changes: u32,

    /// Number of nets that could not be routed.
    pub unrouted_nets: u32,
}

impl RoutingMetrics {
    /// Check if all nets were successfully routed.
    pub fn is_complete(&self) -> bool {
        self.unrouted_nets == 0
    }

    /// Calculate a simple quality score (lower is better).
    ///
    /// Scoring formula:
    /// - Base: total_length in mm
    /// - Penalty: +5mm per via
    /// - Penalty: +1000mm per unrouted net
    ///
    /// This provides a rough measure for comparing routing solutions.
    pub fn quality_score(&self) -> f64 {
        let length_mm = self.total_length.0 as f64 / 1_000_000.0;
        let via_penalty = self.via_count as f64 * 5.0;
        let unrouted_penalty = self.unrouted_nets as f64 * 1000.0;

        length_mm + via_penalty + unrouted_penalty
    }
}

/// Calculate routing metrics from a RoutingResult.
///
/// # Example
///
/// ```
/// use cypcb_router::types::{RoutingResult, RouteSegment, ViaPlacement, calculate_metrics};
/// use cypcb_world::{Layer, NetId};
/// use cypcb_core::{Nm, Point};
///
/// let routes = vec![
///     RouteSegment::new(NetId::new(0), Layer::TopCopper, Nm::from_mm(0.2),
///         Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 0.0)),
/// ];
/// let vias = vec![
///     ViaPlacement::through_hole(NetId::new(0), Point::from_mm(10.0, 0.0), Nm::from_mm(0.3)),
/// ];
///
/// let result = RoutingResult::complete(routes, vias);
/// let metrics = calculate_metrics(&result);
///
/// assert_eq!(metrics.via_count, 1);
/// assert_eq!(metrics.total_length, Nm::from_mm(10.0));
/// ```
pub fn calculate_metrics(result: &RoutingResult) -> RoutingMetrics {
    let total_length = result.total_length();
    let via_count = result.vias.len() as u32;

    // Count layer changes (each via represents a layer change)
    let layer_changes = via_count;

    // Count unrouted nets from status
    let unrouted_nets = match &result.status {
        RoutingStatus::Complete => 0,
        RoutingStatus::Partial { unrouted_count } => *unrouted_count as u32,
        RoutingStatus::Failed { .. } => u32::MAX, // Unknown, assume worst
    };

    RoutingMetrics {
        total_length,
        via_count,
        layer_changes,
        unrouted_nets,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_routing_status() {
        assert!(RoutingStatus::Complete.is_complete());
        assert!(!RoutingStatus::Complete.is_failed());

        let partial = RoutingStatus::Partial { unrouted_count: 5 };
        assert!(!partial.is_complete());
        assert!(!partial.is_failed());

        let failed = RoutingStatus::Failed {
            reason: "timeout".into(),
        };
        assert!(!failed.is_complete());
        assert!(failed.is_failed());
    }

    #[test]
    fn test_route_segment() {
        let seg = RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(10.0, 0.0),
        );

        assert_eq!(seg.net_id, NetId::new(0));
        assert_eq!(seg.layer, Layer::TopCopper);
        assert_eq!(seg.width, Nm::from_mm(0.2));
        assert_eq!(seg.length(), Nm::from_mm(10.0));
    }

    #[test]
    fn test_route_segment_diagonal() {
        // 3-4-5 triangle
        let seg = RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(3.0, 4.0),
        );

        assert_eq!(seg.length(), Nm::from_mm(5.0));
    }

    #[test]
    fn test_via_placement() {
        let via = ViaPlacement::through_hole(
            NetId::new(1),
            Point::from_mm(5.0, 5.0),
            Nm::from_mm(0.3),
        );

        assert_eq!(via.net_id, NetId::new(1));
        assert_eq!(via.position, Point::from_mm(5.0, 5.0));
        assert_eq!(via.drill, Nm::from_mm(0.3));
        assert_eq!(via.start_layer, Layer::TopCopper);
        assert_eq!(via.end_layer, Layer::BottomCopper);
    }

    #[test]
    fn test_routing_result_complete() {
        let routes = vec![RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(10.0, 0.0),
        )];
        let vias = vec![ViaPlacement::through_hole(
            NetId::new(0),
            Point::from_mm(10.0, 0.0),
            Nm::from_mm(0.3),
        )];

        let result = RoutingResult::complete(routes, vias);

        assert!(result.is_complete());
        assert_eq!(result.route_count(), 1);
        assert_eq!(result.via_count(), 1);
        assert_eq!(result.total_length(), Nm::from_mm(10.0));
    }

    #[test]
    fn test_routing_result_partial() {
        let result = RoutingResult::partial(Vec::new(), Vec::new(), 3);

        assert!(!result.is_complete());
        assert_eq!(result.route_count(), 0);

        if let RoutingStatus::Partial { unrouted_count } = result.status {
            assert_eq!(unrouted_count, 3);
        } else {
            panic!("Expected Partial status");
        }
    }

    #[test]
    fn test_routing_result_failed() {
        let result = RoutingResult::failed("Process crashed");

        assert!(!result.is_complete());
        assert!(result.routes.is_empty());
        assert!(result.vias.is_empty());

        if let RoutingStatus::Failed { reason } = result.status {
            assert_eq!(reason, "Process crashed");
        } else {
            panic!("Expected Failed status");
        }
    }

    #[test]
    fn test_routing_result_default() {
        let result = RoutingResult::default();

        assert!(result.is_complete());
        assert!(result.routes.is_empty());
        assert!(result.vias.is_empty());
    }

    #[test]
    fn test_routing_metrics_complete() {
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 3,
            layer_changes: 3,
            unrouted_nets: 0,
        };

        assert!(metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_incomplete() {
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(50.0),
            via_count: 1,
            layer_changes: 1,
            unrouted_nets: 2,
        };

        assert!(!metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_quality_score() {
        // Simple case: 100mm length, 0 vias, 0 unrouted
        let metrics = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 0,
            layer_changes: 0,
            unrouted_nets: 0,
        };

        // Score should be just the length
        assert!((metrics.quality_score() - 100.0).abs() < 0.01);

        // With vias
        let metrics_with_vias = RoutingMetrics {
            total_length: Nm::from_mm(100.0),
            via_count: 2,
            layer_changes: 2,
            unrouted_nets: 0,
        };

        // Score = 100 + (2 * 5) = 110
        assert!((metrics_with_vias.quality_score() - 110.0).abs() < 0.01);
    }

    #[test]
    fn test_calculate_metrics_complete() {
        let routes = vec![
            RouteSegment::new(
                NetId::new(0),
                Layer::TopCopper,
                Nm::from_mm(0.2),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 0.0),
            ),
            RouteSegment::new(
                NetId::new(0),
                Layer::BottomCopper,
                Nm::from_mm(0.2),
                Point::from_mm(10.0, 0.0),
                Point::from_mm(20.0, 0.0),
            ),
        ];
        let vias = vec![ViaPlacement::through_hole(
            NetId::new(0),
            Point::from_mm(10.0, 0.0),
            Nm::from_mm(0.3),
        )];

        let result = RoutingResult::complete(routes, vias);
        let metrics = calculate_metrics(&result);

        assert_eq!(metrics.total_length, Nm::from_mm(20.0));
        assert_eq!(metrics.via_count, 1);
        assert_eq!(metrics.layer_changes, 1);
        assert_eq!(metrics.unrouted_nets, 0);
        assert!(metrics.is_complete());
    }

    #[test]
    fn test_calculate_metrics_partial() {
        let routes = vec![RouteSegment::new(
            NetId::new(0),
            Layer::TopCopper,
            Nm::from_mm(0.2),
            Point::from_mm(0.0, 0.0),
            Point::from_mm(5.0, 0.0),
        )];

        let result = RoutingResult::partial(routes, Vec::new(), 3);
        let metrics = calculate_metrics(&result);

        assert_eq!(metrics.total_length, Nm::from_mm(5.0));
        assert_eq!(metrics.via_count, 0);
        assert_eq!(metrics.unrouted_nets, 3);
        assert!(!metrics.is_complete());
    }

    #[test]
    fn test_routing_metrics_default() {
        let metrics = RoutingMetrics::default();

        assert_eq!(metrics.total_length, Nm(0));
        assert_eq!(metrics.via_count, 0);
        assert_eq!(metrics.layer_changes, 0);
        assert_eq!(metrics.unrouted_nets, 0);
        assert!(metrics.is_complete());
    }
}

[package]
name = "cypcb-router"
version = "0.1.0"
edition = "2021"
description = "Autorouting integration for CodeYourPCB (FreeRouting)"
license.workspace = true
repository.workspace = true

[dependencies]
bevy_ecs = { workspace = true }
cypcb-core = { path = "../cypcb-core" }
cypcb-world = { path = "../cypcb-world", default-features = false }
thiserror = { workspace = true }

//! BoardWorld - High-level API for PCB board entities.
//!
//! Provides a clean wrapper around bevy_ecs::World with PCB-specific
//! operations for creating boards, spawning components, and querying.
//!
//! # Example
//!
//! ```
//! use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
//! use cypcb_core::Nm;
//!
//! // Create a new board world
//! let mut world = BoardWorld::new();
//!
//! // Set up the board
//! let board = world.set_board("MyBoard".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
//!
//! // Intern net names
//! let vcc = world.intern_net("VCC");
//! let gnd = world.intern_net("GND");
//!
//! // Spawn components
//! let r1 = world.spawn_component(
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::ZERO,
//!     FootprintRef::new("0402"),
//!     NetConnections::new(),
//! );
//!
//! // Query the world
//! assert_eq!(world.component_count(), 1);
//! ```

use bevy_ecs::prelude::*;

use cypcb_core::{Nm, Point, Rect};

use crate::components::*;
use crate::registry::NetRegistry;
use crate::spatial::{SpatialEntry, SpatialIndex};

/// High-level wrapper around bevy_ecs::World for PCB board operations.
///
/// BoardWorld provides a clean, type-safe API for:
/// - Creating and configuring the board
/// - Spawning component entities
/// - Interning net names
/// - Spatial queries
/// - Direct ECS access when needed
///
/// # Architecture
///
/// Internally uses bevy_ecs::World with two resources:
/// - [`NetRegistry`]: For interning net names to integer IDs
/// - [`SpatialIndex`]: For efficient region-based queries
///
/// # Example
///
/// ```
/// use cypcb_world::BoardWorld;
/// use cypcb_core::Nm;
///
/// let mut world = BoardWorld::new();
///
/// // Create a 100x80mm 4-layer board
/// world.set_board("MyPCB".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
///
/// // Get board info
/// if let Some((size, layers)) = world.board_info() {
///     println!("Board: {}x{}, {} layers", size.width, size.height, layers.count);
/// }
/// ```
pub struct BoardWorld {
    /// The underlying bevy_ecs World.
    world: World,
    /// Entity ID of the board (if set).
    board_entity: Option<Entity>,
}

impl BoardWorld {
    /// Create a new empty BoardWorld.
    ///
    /// Initializes the ECS world with:
    /// - Empty [`SpatialIndex`] resource
    /// - Empty [`NetRegistry`] resource
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// assert!(world.is_empty());
    /// ```
    pub fn new() -> Self {
        let mut world = World::new();
        world.insert_resource(SpatialIndex::new());
        world.insert_resource(NetRegistry::new());
        BoardWorld {
            world,
            board_entity: None,
        }
    }

    // ========================================================================
    // Board Management
    // ========================================================================

    /// Set the board properties, creating or updating the board entity.
    ///
    /// There can only be one board entity. Calling this multiple times
    /// will update the existing board entity.
    ///
    /// # Arguments
    ///
    /// * `name` - Board name/identifier
    /// * `size` - Board dimensions as (width, height) in nanometers
    /// * `layers` - Number of copper layers (2-32)
    ///
    /// # Returns
    ///
    /// The board entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::Nm;
    ///
    /// let mut world = BoardWorld::new();
    /// let board = world.set_board(
    ///     "TestBoard".to_string(),
    ///     (Nm::from_mm(100.0), Nm::from_mm(80.0)),
    ///     4,
    /// );
    /// ```
    pub fn set_board(&mut self, name: String, size: (Nm, Nm), layers: u8) -> Entity {
        let board_size = BoardSize::new(size.0, size.1);
        let layer_stack = LayerStack::new(layers);
        let name_component = crate::components::metadata::Name(name);

        if let Some(entity) = self.board_entity {
            // Update existing board
            let mut entity_mut = self.world.entity_mut(entity);
            entity_mut.insert((Board, board_size, layer_stack, name_component));
            entity
        } else {
            // Create new board
            let entity = self
                .world
                .spawn((Board, board_size, layer_stack, name_component))
                .id();
            self.board_entity = Some(entity);
            entity
        }
    }

    /// Get the board entity ID if one has been set.
    pub fn board_entity(&self) -> Option<Entity> {
        self.board_entity
    }

    /// Get board size and layer stack if a board has been set.
    ///
    /// # Returns
    ///
    /// Tuple of (BoardSize, LayerStack) if board exists, None otherwise.
    pub fn board_info(&self) -> Option<(BoardSize, LayerStack)> {
        let entity = self.board_entity?;
        let size = self.world.get::<BoardSize>(entity)?;
        let layers = self.world.get::<LayerStack>(entity)?;
        Some((*size, *layers))
    }

    /// Get the board name if one has been set.
    pub fn board_name(&self) -> Option<&str> {
        let entity = self.board_entity?;
        self.world
            .get::<crate::components::metadata::Name>(entity)
            .map(|n| n.0.as_str())
    }

    // ========================================================================
    // Component Spawning
    // ========================================================================

    /// Spawn a new component entity.
    ///
    /// # Arguments
    ///
    /// * `refdes` - Reference designator (R1, C1, U1, etc.)
    /// * `value` - Component value (10k, 100nF, etc.)
    /// * `position` - Position on board
    /// * `rotation` - Rotation angle
    /// * `footprint` - Footprint reference
    /// * `nets` - Net connections for each pin
    ///
    /// # Returns
    ///
    /// The spawned entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    /// ```
    pub fn spawn_component(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets))
            .id()
    }

    /// Spawn a component with a source span for error reporting.
    ///
    /// Same as [`spawn_component`](Self::spawn_component) but also attaches
    /// a [`SourceSpan`] for linking back to source file locations.
    pub fn spawn_component_with_span(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
        span: SourceSpan,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets, span))
            .id()
    }

    /// Spawn an entity with arbitrary components.
    ///
    /// Use this for custom entity types not covered by [`spawn_component`](Self::spawn_component).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Position};
    ///
    /// let mut world = BoardWorld::new();
    /// let entity = world.spawn_entity((
    ///     RefDes::new("J1"),
    ///     Position::from_mm(5.0, 5.0),
    /// ));
    /// ```
    pub fn spawn_entity<B: Bundle>(&mut self, bundle: B) -> Entity {
        self.world.spawn(bundle).id()
    }

    // ========================================================================
    // Net Registry
    // ========================================================================

    /// Intern a net name, returning its unique NetId.
    ///
    /// If the name has already been interned, returns the existing ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let mut world = BoardWorld::new();
    /// let vcc = world.intern_net("VCC");
    /// let vcc2 = world.intern_net("VCC");
    /// assert_eq!(vcc, vcc2); // Same ID
    /// ```
    pub fn intern_net(&mut self, name: &str) -> NetId {
        self.world.resource_mut::<NetRegistry>().intern(name)
    }

    /// Get the name for a NetId.
    ///
    /// Returns None if the ID is invalid.
    pub fn net_name(&self, id: NetId) -> Option<&str> {
        self.world.resource::<NetRegistry>().name(id)
    }

    /// Look up a NetId by name without interning.
    ///
    /// Returns None if the name has not been interned.
    pub fn get_net(&self, name: &str) -> Option<NetId> {
        self.world.resource::<NetRegistry>().get(name)
    }

    /// Get the number of interned nets.
    pub fn net_count(&self) -> usize {
        self.world.resource::<NetRegistry>().len()
    }

    /// Iterate over all interned nets.
    pub fn nets(&self) -> impl Iterator<Item = (NetId, &str)> {
        self.world.resource::<NetRegistry>().iter()
    }

    // ========================================================================
    // Spatial Index
    // ========================================================================

    /// Get a reference to the spatial index.
    ///
    /// Use this for direct spatial queries, iteration, or DRC checks.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// let spatial = world.spatial();
    /// assert!(spatial.is_empty());
    /// ```
    pub fn spatial(&self) -> &SpatialIndex {
        self.world.resource::<SpatialIndex>()
    }

    /// Rebuild the spatial index from current component positions.
    ///
    /// Call this after modifying component positions or spawning
    /// components to update the spatial index for efficient queries.
    ///
    /// # Arguments
    ///
    /// * `footprint_bounds` - Function to get bounds for a footprint name.
    ///   Used to calculate entity bounding boxes.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::{Nm, Rect, Point};
    ///
    /// let mut world = BoardWorld::new();
    /// // ... spawn components ...
    ///
    /// // Rebuild with simple bounds
    /// world.rebuild_spatial_index(|_| Rect::from_center_size(
    ///     Point::ORIGIN,
    ///     (Nm::from_mm(1.0), Nm::from_mm(1.0)),
    /// ));
    /// ```
    pub fn rebuild_spatial_index<F>(&mut self, footprint_bounds: F)
    where
        F: Fn(&str) -> Rect,
    {
        let mut entries = Vec::new();

        // Query all positioned entities with footprints
        let mut query = self
            .world
            .query::<(Entity, &Position, &FootprintRef)>();

        for (entity, position, footprint) in query.iter(&self.world) {
            let bounds = footprint_bounds(footprint.as_str());
            let pos = position.0;

            // Translate bounds by position
            let min = Point::new(
                Nm(pos.x.0 + bounds.min.x.0),
                Nm(pos.y.0 + bounds.min.y.0),
            );
            let max = Point::new(
                Nm(pos.x.0 + bounds.max.x.0),
                Nm(pos.y.0 + bounds.max.y.0),
            );

            // Default to all layers for now (could be refined with pad layer info)
            let layer_mask = 0xFFFFFFFF;

            entries.push(SpatialEntry::new(entity, min, max, layer_mask));
        }

        self.world.resource_mut::<SpatialIndex>().rebuild(entries);
    }

    /// Query entities in a rectangular region.
    ///
    /// Returns all entities whose bounding boxes intersect the given bounds.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    pub fn query_region(&self, bounds: Rect) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region(bounds.min, bounds.max)
            .collect()
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding boxes contain the point.
    pub fn query_point(&self, point: Point) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_point(point)
            .collect()
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `bounds` - The query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(&self, bounds: Rect, layer_mask: u32) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region_on_layers(bounds.min, bounds.max, layer_mask)
            .collect()
    }

    // ========================================================================
    // Entity Queries
    // ========================================================================

    /// Get the number of component entities (excluding board).
    pub fn component_count(&mut self) -> usize {
        let mut query = self.world.query::<&RefDes>();
        query.iter(&self.world).count()
    }

    /// Check if the world is empty (no entities).
    pub fn is_empty(&self) -> bool {
        self.world.entities().len() == 0
    }

    /// Get a component from an entity.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// let refdes = world.get::<RefDes>(r1);
    /// assert_eq!(refdes.map(|r| r.as_str()), Some("R1"));
    /// ```
    pub fn get<T: Component>(&self, entity: Entity) -> Option<&T> {
        self.world.get::<T>(entity)
    }

    /// Get a mutable reference to a component.
    pub fn get_mut<T: Component>(&mut self, entity: Entity) -> Option<Mut<'_, T>> {
        self.world.get_mut::<T>(entity)
    }

    /// Check if an entity has a specific component.
    pub fn has<T: Component>(&self, entity: Entity) -> bool {
        self.world.get::<T>(entity).is_some()
    }

    /// Find an entity by its reference designator.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// assert_eq!(world.find_by_refdes("R1"), Some(r1));
    /// assert_eq!(world.find_by_refdes("R2"), None);
    /// ```
    pub fn find_by_refdes(&mut self, refdes: &str) -> Option<Entity> {
        let mut query = self.world.query::<(Entity, &RefDes)>();
        query
            .iter(&self.world)
            .find(|(_, r)| r.as_str() == refdes)
            .map(|(e, _)| e)
    }

    /// Iterate over all components (entities with RefDes).
    ///
    /// Returns a vector of (Entity, RefDes clone, Position clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn components(&mut self) -> Vec<(Entity, RefDes, Position)> {
        let mut query = self.world.query::<(Entity, &RefDes, &Position)>();
        query
            .iter(&self.world)
            .map(|(e, r, p)| (e, r.clone(), *p))
            .collect()
    }

    /// Iterate over all zones.
    ///
    /// Returns a vector of (Entity, Zone clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn zones(&mut self) -> Vec<(Entity, Zone)> {
        let mut query = self.world.query::<(Entity, &Zone)>();
        query
            .iter(&self.world)
            .map(|(e, z)| (e, z.clone()))
            .collect()
    }

    // ========================================================================
    // Direct ECS Access
    // ========================================================================

    /// Get direct access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced queries not covered by the BoardWorld API.
    pub fn ecs(&self) -> &World {
        &self.world
    }

    /// Get mutable access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced operations not covered by the BoardWorld API.
    pub fn ecs_mut(&mut self) -> &mut World {
        &mut self.world
    }

    // ========================================================================
    // Serialization Helpers
    // ========================================================================

    /// Clear all entities and reset resources.
    pub fn clear(&mut self) {
        self.world.clear_entities();
        self.world.insert_resource(SpatialIndex::new());
        self.world.insert_resource(NetRegistry::new());
        self.board_entity = None;
    }
}

impl Default for BoardWorld {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_world_is_empty() {
        let mut world = BoardWorld::new();
        assert!(world.is_empty());
        assert_eq!(world.component_count(), 0);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_set_board() {
        let mut world = BoardWorld::new();
        let board = world.set_board(
            "TestBoard".to_string(),
            (Nm::from_mm(100.0), Nm::from_mm(80.0)),
            4,
        );

        assert_eq!(world.board_entity(), Some(board));
        assert_eq!(world.board_name(), Some("TestBoard"));

        let (size, layers) = world.board_info().unwrap();
        assert_eq!(size.width, Nm::from_mm(100.0));
        assert_eq!(size.height, Nm::from_mm(80.0));
        assert_eq!(layers.count, 4);
    }

    #[test]
    fn test_spawn_component() {
        let mut world = BoardWorld::new();
        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.component_count(), 1);
        assert_eq!(world.get::<RefDes>(r1).map(|r| r.as_str()), Some("R1"));
        assert_eq!(world.get::<Value>(r1).map(|v| v.as_str()), Some("10k"));
    }

    #[test]
    fn test_intern_net() {
        let mut world = BoardWorld::new();

        let vcc = world.intern_net("VCC");
        let gnd = world.intern_net("GND");
        let vcc2 = world.intern_net("VCC");

        assert_eq!(vcc, vcc2);
        assert_ne!(vcc, gnd);
        assert_eq!(world.net_name(vcc), Some("VCC"));
        assert_eq!(world.net_count(), 2);
    }

    #[test]
    fn test_find_by_refdes() {
        let mut world = BoardWorld::new();

        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let r2 = world.spawn_component(
            RefDes::new("R2"),
            Value::new("4.7k"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.find_by_refdes("R1"), Some(r1));
        assert_eq!(world.find_by_refdes("R2"), Some(r2));
        assert_eq!(world.find_by_refdes("R3"), None);
    }

    #[test]
    fn test_spatial_index() {
        let mut world = BoardWorld::new();

        // Spawn some components at known positions
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("R2"),
            Value::new("10k"),
            Position::from_mm(50.0, 50.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Rebuild with simple 1mm x 1mm bounds
        world.rebuild_spatial_index(|_| {
            Rect::from_center_size(Point::ORIGIN, (Nm::from_mm(1.0), Nm::from_mm(1.0)))
        });

        // Query near R1
        let found = world.query_region(Rect::from_points(
            Point::from_mm(9.0, 9.0),
            Point::from_mm(11.0, 11.0),
        ));
        assert_eq!(found.len(), 1);

        // Query near R2
        let found = world.query_region(Rect::from_points(
            Point::from_mm(49.0, 49.0),
            Point::from_mm(51.0, 51.0),
        ));
        assert_eq!(found.len(), 1);

        // Query covering both
        let found = world.query_region(Rect::from_points(
            Point::from_mm(0.0, 0.0),
            Point::from_mm(100.0, 100.0),
        ));
        assert_eq!(found.len(), 2);

        // Query empty area
        let found = world.query_region(Rect::from_points(
            Point::from_mm(200.0, 200.0),
            Point::from_mm(300.0, 300.0),
        ));
        assert!(found.is_empty());
    }

    #[test]
    fn test_clear() {
        let mut world = BoardWorld::new();

        world.set_board("Test".to_string(), (Nm::from_mm(100.0), Nm::from_mm(100.0)), 2);
        world.intern_net("VCC");
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.clear();

        assert!(world.is_empty());
        assert_eq!(world.board_entity(), None);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_components_iterator() {
        let mut world = BoardWorld::new();

        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("C1"),
            Value::new("100nF"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let components = world.components();
        assert_eq!(components.len(), 2);
    }
}

//! Routing rule trait for the A*-based autorouter.
//!
//! [`RoutingRuleSet`] is the primary interface between the design rules system
//! and the routing engine. It must be object-safe so it can be stored as
//! `dyn RoutingRuleSet` in the router.
//!
//! # Layer indices
//!
//! This module uses `u8` layer indices instead of importing `cypcb-world`'s
//! `Layer` enum, keeping `cypcb-rules` as a leaf crate. Convention:
//! - 0 = top copper
//! - 1 = inner-1
//! - N = bottom copper (where N = total_copper_layers - 1)

use crate::constraints::DesignConstraints;
use crate::signal_class::{SignalClass, SignalClassConstraints};
use cypcb_core::Nm;

/// Rule set interface for routing and DRC engines.
///
/// This trait is designed to be object-safe (`dyn RoutingRuleSet` compiles).
/// All methods take `&self` and return owned or reference types — no generics,
/// no `Self`-returning methods.
///
/// # For autorouter integration
///
/// The A* router uses:
/// - [`constraints_for_net`](RoutingRuleSet::constraints_for_net) to get per-net clearances and widths
/// - [`via_cost`](RoutingRuleSet::via_cost) to penalize layer transitions
/// - [`layer_change_cost`](RoutingRuleSet::layer_change_cost) to bias routing toward preferred layers
/// - [`clearance_between`](RoutingRuleSet::clearance_between) to check spacing between different nets
///
/// # Examples
///
/// ```
/// use cypcb_rules::{RoutingRuleSet, DesignConstraints, SignalClass, SignalClassConstraints};
/// use cypcb_core::Nm;
///
/// struct SimpleRules {
///     constraints: DesignConstraints,
/// }
///
/// impl RoutingRuleSet for SimpleRules {
///     fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
///         &self.constraints
///     }
///
///     fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
///         class.default_constraints()
///     }
///
///     fn via_cost(&self, _from_layer: u8, _to_layer: u8) -> f64 {
///         1.0
///     }
///
///     fn layer_change_cost(&self, _layer: u8) -> f64 {
///         0.5
///     }
///
///     fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
///         self.constraints.min_clearance
///     }
/// }
///
/// let rules = SimpleRules { constraints: DesignConstraints::default() };
/// let _: &dyn RoutingRuleSet = &rules; // object-safe
/// ```
pub trait RoutingRuleSet {
    /// Get the design constraints applicable to a specific net.
    ///
    /// For simple designs, this may return the same constraints for all nets.
    /// Advanced designs may have per-net overrides.
    fn constraints_for_net(&self, net_id: u32) -> &DesignConstraints;

    /// Get the signal-class-specific constraints.
    ///
    /// Returns an owned [`SignalClassConstraints`] because classes may be
    /// computed dynamically.
    fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints;

    /// Cost of placing a via transitioning between two layers.
    ///
    /// Higher values discourage the router from adding vias. Typical range:
    /// - 0.5–2.0 for standard vias
    /// - 5.0+ for blind/buried vias (more expensive to fabricate)
    /// - `f64::INFINITY` to prohibit a transition entirely
    fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64;

    /// Cost of routing on a specific layer.
    ///
    /// Used by the A* router to bias routing toward preferred layers.
    /// Lower values = preferred. Typical range: 0.1–2.0.
    fn layer_change_cost(&self, layer: u8) -> f64;

    /// Minimum clearance required between two specific nets.
    ///
    /// Allows net-pair-specific spacing rules (e.g. high-voltage isolation
    /// between power nets and signal nets).
    fn clearance_between(&self, net_a: u32, net_b: u32) -> Nm;
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Minimal implementation to verify the trait is object-safe and usable.
    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }

        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }

        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 0.5
        }

        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 { 0.1 } else { 1.0 }
        }

        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn test_trait_object_safe() {
        let rules = TestRules::new();
        // This line proves object safety — if it compiles, dyn dispatch works.
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let c = dyn_rules.constraints_for_net(0);
        assert_eq!(c.min_clearance, DesignConstraints::default().min_clearance);
    }

    #[test]
    fn test_via_cost_scales_with_span() {
        let rules = TestRules::new();
        let cost_1 = rules.via_cost(0, 1);
        let cost_2 = rules.via_cost(0, 2);
        assert!(cost_2 > cost_1, "Multi-layer via should cost more");
    }

    #[test]
    fn test_layer_change_cost() {
        let rules = TestRules::new();
        assert!(rules.layer_change_cost(0) < rules.layer_change_cost(1));
    }

    #[test]
    fn test_clearance_between_returns_nm() {
        let rules = TestRules::new();
        let clearance = rules.clearance_between(1, 2);
        assert!(clearance.raw() > 0);
    }

    #[test]
    fn test_constraints_for_class() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let power = dyn_rules.constraints_for_class(SignalClass::Power);
        let digital = dyn_rules.constraints_for_class(SignalClass::Digital);
        assert!(power.min_trace_width.raw() > digital.min_trace_width.raw());
    }

    #[test]
    fn test_dyn_dispatch_all_methods() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;

        // Exercise every trait method through dyn dispatch
        let _ = dyn_rules.constraints_for_net(42);
        let _ = dyn_rules.constraints_for_class(SignalClass::HighSpeed);
        let _ = dyn_rules.via_cost(0, 3);
        let _ = dyn_rules.layer_change_cost(1);
        let _ = dyn_rules.clearance_between(10, 20);
    }
}

//! CodeYourPCB World
//!
//! ECS-based board model using bevy_ecs.
//! Provides the runtime representation of PCB designs.
//!
//! # Architecture
//!
//! This crate uses an Entity Component System (ECS) architecture from bevy_ecs.
//! PCB elements are represented as entities composed of small, focused components.
//!
//! ## Why ECS?
//!
//! - **Composition over inheritance**: Combine components flexibly
//! - **Cache-friendly**: Contiguous memory layout for fast iteration
//! - **Parallel queries**: bevy_ecs supports parallel iteration
//! - **Decoupled systems**: Components and systems are independent
//!
//! # Components
//!
//! Components are organized into categories:
//!
//! - **Position**: [`Position`], [`Rotation`] - spatial placement
//! - **Electrical**: [`NetId`], [`RefDes`], [`Value`], [`NetConnections`] - electrical properties
//! - **Physical**: [`Layer`], [`FootprintRef`], [`Pad`], [`PadShape`] - physical properties
//! - **Board**: [`Board`], [`BoardSize`], [`LayerStack`] - board-level properties
//! - **Metadata**: [`SourceSpan`], [`ComponentKind`] - source tracking
//!
//! # Entity Examples
//!
//! A resistor entity might have:
//! ```text
//! Entity: R1
//!   - RefDes("R1")
//!   - Value("10k")
//!   - Position at (10mm, 20mm)
//!   - Rotation at 90 degrees
//!   - FootprintRef("0402")
//!   - NetConnections { "1" -> VCC, "2" -> GND }
//!   - SourceSpan pointing to source file
//! ```
//!
//! A board entity might have:
//! ```text
//! Entity: Board
//!   - Board (marker)
//!   - BoardSize(100mm x 80mm)
//!   - LayerStack(4 layers)
//! ```
//!
//! # Example Usage
//!
//! ```
//! use bevy_ecs::prelude::*;
//! use cypcb_world::*;
//! use cypcb_core::Point;
//!
//! // Create a world
//! let mut world = World::new();
//!
//! // Spawn a board entity
//! world.spawn((
//!     Board,
//!     BoardSize::from_mm(100.0, 80.0),
//!     LayerStack::new(2),
//! ));
//!
//! // Spawn a resistor entity
//! let vcc = NetId::new(0);
//! let gnd = NetId::new(1);
//!
//! let mut nets = NetConnections::new();
//! nets.add(PinConnection::new("1", vcc));
//! nets.add(PinConnection::new("2", gnd));
//!
//! world.spawn((
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::from_degrees(90.0),
//!     FootprintRef::new("0402"),
//!     nets,
//! ));
//!
//! // Query all components with position
//! let mut query = world.query::<(&RefDes, &Position)>();
//! for (refdes, pos) in query.iter(&world) {
//!     println!("{} at {}", refdes, pos);
//! }
//! ```

